package com.oms.supplychain.service.wms;

import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import org.w3c.dom.Element;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;
import static com.oms.supplychain.service.wms.WmsStore.*;

/** Verify exact wire body before interpreting delivery quantities and package contents. */
final class WmsOutboundCallbackParser {
    private static final DateTimeFormatter TIME=DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss");
    private static void verify(Map<String,Object> c,String secret,Map<String,String> p,String body,String method){require(body.getBytes(StandardCharsets.UTF_8).length<=1024*1024,"出库回传超过1MB");require(method.equals(p.get("method"))&&"2.0".equals(p.get("v"))&&"2.0".equals(text(c.get("api_version")))&&"md5".equals(p.get("sign_method")),"出库回传动作、版本或签名算法不匹配");require(text(c.get("app_key")).equals(p.get("app_key"))&&text(c.get("customer_id")).equals(text(p.get("customerId"))),"回传应用或客户不匹配");LocalDateTime sent;try{sent=LocalDateTime.parse(p.get("timestamp"),TIME);}catch(Exception e){throw new IllegalArgumentException("回传时间格式错误");}require(Math.abs(Duration.between(sent,LocalDateTime.now(ZoneId.of("Asia/Shanghai"))).getSeconds())<=600,"回传时间超出允许范围");require(MessageDigest.isEqual(QimenProtocol.sign(p,body,secret).getBytes(StandardCharsets.UTF_8),text(p.get("sign")).getBytes(StandardCharsets.UTF_8)),"出库回传验签失败");}
    private static String value(Element e,String name){Element child=QimenProtocol.child(e,name);return child==null?"":child.getTextContent().trim();}
    private static long qty(String value){require(!value.isEmpty(),"出库回传缺少数量");long quantity=id(value);require(quantity>=0&&quantity<=100000000,"出库回传数量无效");return quantity;}
    private static void head(WmsProtocol.OutboundReceipt r,String confirmType){require(confirmType.isEmpty()||Arrays.asList("0","1").contains(confirmType),"出库确认类型无效");require(Arrays.asList("","PARTDELIVERED","DELIVERED").contains(r.status),"仅支持实际发货确认回传，其他状态请通过仓库查询核对");r.complete="0".equals(confirmType)||"DELIVERED".equals(r.status);if(r.status.isEmpty())r.status=r.complete?"DELIVERED":"PARTDELIVERED";require(!r.messageId.isEmpty()&&r.messageId.length()<=128,"出库回传缺少有效消息ID");if(!r.outboundTime.isEmpty())try{LocalDateTime.parse(r.outboundTime,TIME);}catch(Exception e){throw new IllegalArgumentException("实际出库时间格式错误");}}
    private static WmsProtocol.OutboundLine line(String no,String sku,String owner,String batch,String type,long quantity){require(type.isEmpty()||"ZP".equals(type),"当前发货单仅支持正品出库回传");WmsProtocol.OutboundLine l=new WmsProtocol.OutboundLine();l.lineNo=no;l.sku=sku;l.owner=owner;l.batch=batch;l.quantity=quantity;return l;}
    static WmsProtocol.OutboundReceipt qimen(Map<String,Object> c,String secret,Map<String,String> p,String body){verify(c,secret,p,body,"taobao.qimen.deliveryorder.confirm");Element root=QimenProtocol.parse(body);require("request".equals(root.getTagName()),"出库回传须为request报文");Element h=QimenProtocol.child(root,"deliveryOrder");require(h!=null,"回传缺少发货单信息");WmsProtocol.OutboundReceipt r=new WmsProtocol.OutboundReceipt();r.shipmentSn=value(h,"deliveryOrderCode");r.externalOrder=value(h,"deliveryOrderId");r.messageId=value(h,"outBizCode");r.warehouse=value(h,"warehouseCode");r.owner=value(h,"ownerCode");r.status=value(h,"status");r.outboundTime=value(h,"orderConfirmTime");head(r,value(h,"confirmType"));if(!value(h,"totalOrderLines").isEmpty())r.totalLines=Math.toIntExact(qty(value(h,"totalOrderLines")));
        Element lines=QimenProtocol.child(root,"orderLines");if(lines!=null)for(Element l:QimenProtocol.children(lines,"orderLine")){r.sourceLineCount++;String no=value(l,"orderLineNo"),sku=value(l,"itemCode"),owner=value(l,"ownerCode");long actual=qty(value(l,"actualQty"));Element batches=QimenProtocol.child(l,"batchs");if(batches!=null&&!QimenProtocol.children(batches,"batch").isEmpty()){long sum=0;for(Element b:QimenProtocol.children(batches,"batch")){long quantity=qty(value(b,"actualQty"));sum=Math.addExact(sum,quantity);r.lines.add(line(no,sku,owner,value(b,"batchCode"),value(b,"inventoryType"),quantity));}require(sum==actual,"出库批次数量与行数量不一致");}else r.lines.add(line(no,sku,owner,value(l,"batchCode"),value(l,"inventoryType"),actual));}
        Element packages=QimenProtocol.child(root,"packages");if(packages!=null)for(Element pkg:QimenProtocol.children(packages,"package")){WmsProtocol.OutboundPackage pack=new WmsProtocol.OutboundPackage();pack.packageCode=value(pkg,"packageCode");pack.expressCode=value(pkg,"expressCode");pack.logisticsCode=value(pkg,"logisticsCode");pack.logisticsName=value(pkg,"logisticsName");Element items=QimenProtocol.child(pkg,"items");if(items!=null)for(Element item:QimenProtocol.children(items,"item")){WmsProtocol.PackageItem i=new WmsProtocol.PackageItem();i.sku=value(item,"itemCode");i.quantity=qty(value(item,"quantity"));pack.items.add(i);}r.packages.add(pack);}return r;
    }
    static WmsProtocol.OutboundReceipt hufu(Map<String,Object> c,String secret,Map<String,String> p,String body){verify(c,secret,p,body,"jingdong.hufu.deliveryorder.confirm");JsonNode root;try{root=new ObjectMapper().enable(JsonParser.Feature.STRICT_DUPLICATE_DETECTION).readTree(body);}catch(Exception e){throw new IllegalArgumentException("虎符出库JSON格式错误");}require(root!=null&&root.isObject(),"虎符出库回传须为对象");JsonNode h=root.path("deliveryOrder");require(h.isObject(),"虎符回传缺少发货单信息");WmsProtocol.OutboundReceipt r=new WmsProtocol.OutboundReceipt();r.shipmentSn=h.path("deliveryOrderCode").asText();r.externalOrder=h.path("deliveryOrderId").asText();r.messageId=h.path("outBizCode").asText();r.warehouse=h.path("warehouseCode").asText();r.owner=h.path("ownerCode").asText();r.status=h.path("status").asText();r.outboundTime=h.path("orderConfirmTime").asText();head(r,h.path("confirmType").asText());if(h.hasNonNull("totalOrderLines"))r.totalLines=Math.toIntExact(qty(h.path("totalOrderLines").asText()));JsonNode lines=root.path("orderLines");require(lines.isMissingNode()||lines.isArray(),"虎符出库明细须为数组");for(JsonNode l:lines){r.sourceLineCount++;long actual=qty(l.path("actualQty").asText());JsonNode batches=l.path("batchs");require(batches.isMissingNode()||batches.isArray(),"虎符出库批次须为数组");if(batches.isArray()&&batches.size()>0){long sum=0;for(JsonNode b:batches){long quantity=qty(b.path("actualQty").asText());sum=Math.addExact(sum,quantity);r.lines.add(line(l.path("orderLineNo").asText(),l.path("itemCode").asText(),l.path("ownerCode").asText(),b.path("batchCode").asText(),b.path("inventoryType").asText(),quantity));}require(sum==actual,"虎符出库批次数量与行数量不一致");}else r.lines.add(line(l.path("orderLineNo").asText(),l.path("itemCode").asText(),l.path("ownerCode").asText(),l.path("batchCode").asText(),l.path("inventoryType").asText(),actual));}JsonNode packages=root.path("packages");require(packages.isMissingNode()||packages.isArray(),"虎符包裹须为数组");for(JsonNode pkg:packages){WmsProtocol.OutboundPackage pack=new WmsProtocol.OutboundPackage();pack.packageCode=pkg.path("packageCode").asText();pack.expressCode=pkg.path("expressCode").asText();pack.logisticsCode=pkg.path("logisticsCode").asText();pack.logisticsName=pkg.path("logisticsName").asText();JsonNode items=pkg.path("items");require(items.isArray(),"虎符包裹商品须为数组");for(JsonNode item:items){WmsProtocol.PackageItem i=new WmsProtocol.PackageItem();i.sku=item.path("itemCode").asText();i.quantity=qty(item.path("quantity").asText());pack.items.add(i);}r.packages.add(pack);}return r;
    }
}
